Public static String[] TopEarners (BasketballPlayer[]arr, double amount)
{
    int count = 0; // אורך מערך השמות
    int g = 0 ; // המיקום במערך השמות
    For (int i = 0; i < arr.length ; i++ )
    {
        if (arr[i].TotalEarnings() > amount ) // בדיקה אם סכום השכר
                                              // גדול מהמספר הנתון
            count++ ;
    }
    String [] name = new String [count] ; // יצירת מערך שמות לפי אורך
                                          // של count
    For (int i = 0 ; i < arr.length ; i++ )
    {
        if (arr[i].TotalEarning() > amount )
        {
            name[g] = arr[i].GetName() ; // הוספת השם
                                         // הרלוונטי למערך
            g++ ; // קידום המקום
        }
    }
    return name ; // החזרת מערך השמות
}

Public bool IsSimilarWorkShop (workShop other)
{
    if (this.name == other.name) // האם הסדנאות דומות לפי שם
        return true;
    return false;
}

Public bool HandleNewWorkShop(workShop ws)
{
    for (int i = 0; i < countWorkShops ; i++)
    {
        if (workShop[i].IsSimilarWorkShop(ws) == true) // אם סדנה במערך שקיימת
                                                       // דומה לסדנה שקיבלנו
        {
            if ( (workShop[i].GetPeople() + ws.GetPeople()) <= 40 ) // בודקים אם יש מקום
            {
                workShop[i].GetPeople() += ws.GetPeople() ; // אם יש מקום מוסיפים
                                                            // את מספר האנשים
                                                            // מהסדנה החדשה לקיימת
                return true;
            }
        }
    }
    if (countWorkShops < 200) // לא נמצאה סדנה דומה בבדיקה אם יש מקום
                              // לסדנה חדשה
    {
        workShop [countWorkShop] = ws ; // יש הוספה
        countWorkShops++ ; // קידום מספר התא
        return true ;
    }
    return false ; // לא נמצא מקום בסדנה קיימת ואין מקום במערך
}

